  "rewrite_sql": "-- Set timeouts so the migration fails fast instead of queueing behind production traffic
SET lock_timeout = '2s';
SET statement_timeout = '10s';

-- Add new bigint column (nullable initially to avoid table rewrite)
ALTER TABLE orders ADD COLUMN total_cents_bigint bigint;

-- Backfill existing rows (simple copy operation, extend timeout slightly)
SET statement_timeout = '30s';
UPDATE orders SET total_cents_bigint = total_cents WHERE total_cents_bigint IS NULL;

-- Create trigger to keep both columns in sync during the transition period
CREATE OR REPLACE FUNCTION sync_total_cents_to_bigint()
RETURNS TRIGGER AS $$
BEGIN
  NEW.total_cents_bigint := NEW.total_cents;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER sync_total_cents_bigint_trigger
  BEFORE INSERT OR UPDATE ON orders
  FOR EACH ROW
  EXECUTE FUNCTION sync_total_cents_to_bigint();",
  "notes": "Rewrote the integer→bigint type change using the dual-column pattern to avoid a blocking table rewrite. Added lock_timeout and statement_timeout at the top. Created total_cents_bigint column, backfilled it with existing values, and added a trigger to maintain both columns in sync. The contract phase (renaming total_cents_bigint → total_cents and dropping the old integer column) is deliberately deferred to a later migration that ships after the application has been updated to read from/write to total_cents_bigint or dual-read both columns.",
